def _run(src):
    from pysad.ffscmd import run_sad_string
    buf = io.StringIO()
    run_sad_string(src, out=buf)
    return buf.getvalue().split('\n')


@pytest.mark.parametrize('src,tab,rows', [(A1_SRC, A1_TAB, A1_ROWS), (A2_SRC, A2_TAB, A2_ROWS), (A4_SRC, A4_TAB, A4_ROWS), (E1_SRC, E1_TAB, E1_ROWS), (E5_SRC, E5_TAB, E5_ROWS), (A6_SRC, A6_TAB, A6_ROWS), (F1_SRC, F1_TAB, F1_ROWS)],
                         ids=['wakeopt_two_orbits_fit_table', 'wakeopt_three_orbits_odd', 'wakeopt_nbunch_sigz_two_wake_elements', 'wakeopt_four_orbits_offset_wake_elements', 'wakeopt_twiss_form_orbit', 'initial_orbits_without_wakeopt', 'wakeopt_odd_orbits_ddp_table'])
def test_wake_optics_matches_sad(src, tab, rows):
    lines = _run(src)
    i = [j for j, l in enumerate(lines) if l.startswith(' Matched') or l.startswith(' Residual')][0]
    got = [l for l in lines[i:i + 12] if l.strip() and 'FORM' not in l and 'Do[' not in l and not re.match(r'^ +\d+\.0000000000 ', l)]
    assert got == tab
    tw = [l for l in lines if re.match(r'^ +\d+\.0000000000 ', l)]
    assert len(tw) == len(rows)
    for l, r in zip(tw, rows):
        v = [float(t) for t in l.split()[1:]]
        for a, b in zip(v, r):
            # 軌道の z は SAD が δ の飛行時間 (dvemit) を足す分だけ pysad の INS と違う (δ L/γ² 程度)。それ以外は 1e-8 以内
            assert a == pytest.approx(b, rel=2e-8, abs=3e-14)


def test_wake_optics_has_an_effect():
    # WAKEOPT を切ると、中心の軌道は他の軌道のウェイクを受けない
    on = _run(A1_SRC)
    off = _run(A1_SRC.replace('WAKEOPT; ', ''))
    d_on = [l for l in on if re.match(r'^ +12\.0000000000 ', l)][0]
    d_off = [l for l in off if re.match(r'^ +12\.0000000000 ', l)][0]
    assert d_on != d_off
    assert float(d_off.split()[6]) == 0.0 and float(d_on.split()[6]) != 0.0

